def get_input():
    """Get user input and validate it."""
    while True:
        try:
            user_input = input("Enter a value to convert to different data types (or type 'quit' to exit): ")
            if user_input.lower() == 'quit':
                return
            value = float(user_input)
            return value
        except ValueError:
            print("Invalid input. Please enter a number or type 'quit' to exit.")

def convert_to_types(value):
    """Convert the given value to different data types and return a dictionary."""
    result = {
        'Integer': int(value),
        'Float': float(value),
        'Boolean': bool(value)
    }
    return result

def main():
    value = get_input()
    if value is not None:
        result = convert_to_types(value)
        for key, value in result.items():
            print(f"{key}: {value}")

if __name__ == "__main__":
    main()
```
